  const member=members.find(m=>m.id===badge.user_id)||{id:badge.user_id,name:'Former member'};
  const b=node('button',(badge.revoked?'Revoked badge: ':'Revoke badge: ')+member.name+' · ID '+member.id.slice(0,8)+' · badge '+badge.id.slice(0,8));
  b.disabled=!!badge.revoked;b.style='display:block;width:100%;margin:8px 0;background:#dce6ee';
