async function addReturn(e){const generation=identityGeneration,instance=identityInstance,revision=routeRevision;clearItemActionOffer();if(returnBusy||returnKey)return;if(!returnReady()){renderReturn('Choose a badge or continue as an unidentified returner');return}if(returnCart.some(t=>t.entity.id===e.id)){renderReturn('Already selected');return}try{if(await maybeKit(e,'return'))return;if(!returnMode||!returnReady()||generation!==identityGeneration||instance!==identityInstance||revision!==routeRevision)return;const response=await fetch('/api/entity?id='+encodeURIComponent(e.id));const data=await response.json();if(!response.ok)throw Error(data.error||'Could not read asset');if(!returnMode||!returnReady()||generation!==identityGeneration||instance!==identityInstance||revision!==routeRevision)return;if(data.entity.entityType?.isLocation||data.entity.quantity!==1){renderReturn('Select individually tracked equipment');return}const custodyResponse=await fetch('/api/custody');if(!custodyResponse.ok)throw Error('Could not verify custody');const custody=await custodyResponse.json();if(!returnMode||!returnReady()||generation!==identityGeneration||instance!==identityInstance||revision!==routeRevision)return;if(!Array.isArray(custody))throw Error('Could not verify custody');if(!custody.some(t=>t.entity_id===e.id)){if(data.entity.archived){renderReturn('Archived equipment cannot be checked out');return}itemActionOffer={mode:'checkout',entity:data.entity,sourceMode:'return',generation,instance};renderReturn('This equipment is not checked out');return}if(returnCart.some(t=>t.entity.id===e.id))return;itemActionOffer=null;returnCart.push({entity:data.entity,previous:data.condition,condition:null,destination_id:null,note:null});returnKey=null;renderReturn()}catch(error){if(returnMode&&generation===identityGeneration&&instance===identityInstance&&revision===routeRevision)renderReturn(error.message)}}
