async function confirmReturn(){if(returnBusy||!returnReady()||!returnCart.length)return;const generation=identityGeneration,instance=identityInstance;returnBusy=true;returnKey=returnKey||crypto.randomUUID();const targets=returnCart.map(t=>({entity_id:t.entity.id,condition:t.condition,destination_id:t.destination_id,clear_destination:!!t.clear_destination,note:t.note,return_note:t.return_note}));renderReturn();let failure='';try{const response=await fetch('/return/confirm',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({targets,kit_versions:returnKitVersions,request_key:returnKey,session_generation:generation,session_instance:instance,anonymous_return:anonymousReturn})});const data=await response.json();if(!response.ok)throw Error(data.error||'Return not confirmed');if(generation!==identityGeneration||instance!==identityInstance)return;await transactionDone('return',data.count,anonymousReturn?'Unidentified returner':document.querySelector('#identity').textContent)}catch(error){if(generation===identityGeneration&&instance===identityInstance){const saved=await resolveTransaction(returnKey);if(saved.status==='completed'){await transactionDone('return',targets.length,anonymousReturn?'Unidentified returner':document.querySelector('#identity').textContent);return}if(['not_started','cancelled'].includes(saved.status)){returnKey=null;failure=error.message+' No changes were made. You can correct the list and review it again.'}else failure=error.message+' Check the saved result or open recovery.'}}finally{returnBusy=false;if(returnMode){renderReturn(failure);if(returnKey)recoveryActions(view.querySelector('.checkout-shell'),returnKey,'return')}}}
